import { useDispatch, useSelector } from 'react-redux';
import { useEffect, useState } from 'react';
import { Button, Card, Chip, Tooltip } from '@mui/material';
import HealthAndSafetyIcon from '@mui/icons-material/HealthAndSafety';
import { DataGrid } from '@mui/x-data-grid';
import { IconButton } from '@mui/material';
import EditIcon from '@mui/icons-material/Edit';
import DeleteIcon from '@mui/icons-material/Delete';
import PaymentIcon from '@mui/icons-material/Payment';
import HistoryIcon from '@mui/icons-material/History';
import { toast } from 'react-toastify';
import {
  deleteAppointment,
  getAllAppointments,
  updateAppointment,
} from '../../apis/appointmentSlice';
import moment from 'moment/moment';
import FilterAltIcon from '@mui/icons-material/FilterAlt';
import SearchDoctor from '../../components/Autocomplete/SearchDoctor';
import SearchPatient from '../../components/Autocomplete/SearchPatient';
import { DateRange } from 'react-date-range';
import 'react-date-range/dist/styles.css'; // main style file
import 'react-date-range/dist/theme/default.css'; // theme css
import WorkspacePremiumIcon from '@mui/icons-material/WorkspacePremium';
import { useNavigate } from 'react-router';
import AssessmentIcon from '@mui/icons-material/Assessment';
import Style from '../patientForm/doctor.module.scss';
import PatientFormDialog from '../patientForm/PatientFormDialog';
import PaymentDialog from '../patientForm/PaymentDialog';
import TransactionHistoryDialog from '../patientForm/TransactionHistoryDialog';
import { set } from 'lodash';
import HowToRegIcon from '@mui/icons-material/HowToReg';
import CheckCircleOutlineIcon from '@mui/icons-material/CheckCircleOutline';
import CancelIcon from '@mui/icons-material/Cancel';

export default function AppointmentPage({ search }) {
  const dispatch = useDispatch();
  const navigate = useNavigate();

  const [page, setPage] = useState(0);
  const [pageSize, setPageSize] = useState(5);
  const [filter, setFilter] = useState(false);
  const [patientData, setPatientData] = useState(null);
  const [doctorData, setDoctorData] = useState(null);
  const [isDisabled, setIsDisabled] = useState(true);
  const [message, setMessage] = useState('');
  const [dateRange, setDateRange] = useState([
    {
      startDate: null,
      endDate: null,
      key: 'selection',
      color: '#3d91ff',
    },
  ]);
  const [open, setOpen] = useState(false);
  const [editData, setEditData] = useState({});
  const [operationMode, setOperationMode] = useState('Edit');
  const [openPayment, setOpenPayment] = useState(false);
  const [openTransaction, setOpenTransaction] = useState(false);
  const [selectedApptId, setSelectedApptId] = useState(null);
  const [selectedApptData, setSelectedApptData] = useState(null);

  const { loggedIn } = useSelector((state) => state.authData);
  const { appointments, apptLoading } = useSelector((state) => state.appointmentData);

  const totalCount = appointments?.length || 0;

  async function callApi() {
    // const payload = {
    //   page,
    //   pageSize,
    //   search: search || '',
    //   patient: patientData?.patient?.value || patientData?.patient || patientData?.value || '',
    //   doctor: doctorData?.doctor?.value || doctorData?.doctor || doctorData?.value || '',
    // };

    const payload = {
      page,
      pageSize,
      search: search || '',
      doctorId: doctorData?.doctor?.value || doctorData?.value || '',
      patientId: patientData?.patient?.value || patientData?.value || '',
      startDate: dateRange[0]?.startDate ? moment(dateRange[0].startDate).format('YYYY-MM-DD') : '',
      endDate: dateRange[0]?.endDate ? moment(dateRange[0].endDate).format('YYYY-MM-DD') : '',
      uniquePatient: !doctorData && !patientData && !dateRange[0]?.startDate, // ⭐ if no filter applied → only unique patients
    };

    // if (dateRange[0]?.startDate)
    //   payload.startDate = moment(dateRange[0].startDate).format('DD/MM/YYYY');
    // if (dateRange[0]?.endDate) payload.endDate = moment(dateRange[0].endDate).format('DD/MM/YYYY');

    if (dateRange[0]?.startDate)
      payload.startDate = moment(dateRange[0].startDate).format('YYYY-MM-DD');

    if (dateRange[0]?.endDate) payload.endDate = moment(dateRange[0].endDate).format('YYYY-MM-DD');

    dispatch(getAllAppointments(payload));
  }

  useEffect(() => {
    callApi();
  }, [page, pageSize, dispatch, loggedIn, search, patientData, doctorData, dateRange]);

  useEffect(() => {
    if (doctorData == null) {
      setIsDisabled(true);
      return setMessage('Please select a doctor');
    } else if (patientData == null) {
      setIsDisabled(true);
      return setMessage('Please select a patient');
    } else if (dateRange && dateRange[0]?.startDate == null) {
      setIsDisabled(true);
      return setMessage('Please select a date');
    } else {
      setIsDisabled(false);
      return setMessage('');
    }
  }, [patientData, doctorData, dateRange]);

  const reportUrl = `${process.env.REACT_APP_BACKEND_API}/appointment/generatereport?doctor=${
    doctorData?.doctor?.value || doctorData?.value || ''
  }&patient=${patientData?.patient?.value || patientData?.value || ''}&startDate=${moment(
    dateRange[0]?.startDate,
  ).format('DD/MM/YYYY')}&endDate=${moment(dateRange[0]?.endDate).format('DD/MM/YYYY')}`;

  const receiptUrl = `${process.env.REACT_APP_BACKEND_API}/appointment/generatereceipt?doctor=${
    doctorData?.doctor?.value || doctorData?.value || ''
  }&patient=${patientData?.patient?.value || patientData?.value || ''}&startDate=${moment(
    dateRange[0]?.startDate,
  ).format('DD/MM/YYYY')}&endDate=${moment(dateRange[0]?.endDate).format('DD/MM/YYYY')}`;

  const prescriptionUrl = `${
    process.env.REACT_APP_BACKEND_API
  }/appointment/generateprescription?doctor=${
    doctorData?.doctor?.value || doctorData?.value || ''
  }&patient=${patientData?.patient?.value || patientData?.value || ''}&startDate=${moment(
    dateRange[0]?.startDate,
  ).format('DD/MM/YYYY')}&endDate=${moment(dateRange[0]?.endDate).format('DD/MM/YYYY')}`;

  const handlePaginationModelChange = (model) => {
    setPage(model.page);
    setPageSize(model.pageSize);
  };

  const handleEdit = (data) => {
    // navigate(`/appointmentform/${data._id}`);
    setOpen(true);
    setEditData(data);
    setOperationMode('Edit');
  };

  const handleVisitStatus = (data) => {
    dispatch(updateAppointment({ ...data, visitStatus: true })).then(() => {
      callApi();
    });
  };

  const handleDelete = async (data) => {
    const response = await dispatch(deleteAppointment(data._id));

    if (response?.payload?.success) {
      toast.success(response?.payload.message);
      callApi();
    } else {
      toast.error('Error deleting appointment');
    }
  };

  const columns = [
    {
      field: 'actions',
      headerName: <div className="gridHeaderText">Actions</div>,
      width: 300,
      sortable: false,
      filterable: false,
      renderCell: (params) => (
        <div>
          <Tooltip title="Edit">
            <IconButton
              onClick={() => handleEdit(params.row)}
              color="primary"
              aria-label="edit"
              disabled={params.row.docApproval == 'rejected'}
            >
              <EditIcon />
            </IconButton>
          </Tooltip>

          <Tooltip title="Delete">
            <IconButton onClick={() => handleDelete(params.row)} color="error" aria-label="delete">
              <DeleteIcon />
            </IconButton>
          </Tooltip>

          <Tooltip title="Generate Certificate">
            <IconButton
              onClick={() => {
                const url = `${process.env.REACT_APP_BACKEND_API}/appointment/generatecertificate?id=${params.row._id}`;
                window.open(url, '_blank');
              }}
              color="success"
              aria-label="generate-certificate"
              disabled={params.row.docApproval == 'rejected'}
            >
              <WorkspacePremiumIcon />
            </IconButton>
          </Tooltip>

          <Tooltip title="Assessment Form">
            <IconButton
              onClick={() => {
                navigate(`/assessmentform/${params.row.patientFormId}`);
              }}
              color="secondary"
              aria-label="generate-certificate"
              disabled={params.row.docApproval == 'rejected'}
            >
              <AssessmentIcon />
            </IconButton>
          </Tooltip>
          {params.row.visitStatus !== true && (
            <Tooltip title="Visit Status">
              <IconButton
                onClick={() => handleVisitStatus(params.row)}
                color="info"
                aria-label="visit-status"
                disabled={params.row.docApproval == 'rejected'}
              >
                <HowToRegIcon />
              </IconButton>
            </Tooltip>
          )}
          {params.row.remainingAmount > 0 && (
            <Tooltip title="Add Payment">
              <IconButton
                onClick={() => {
                  setSelectedApptId(params.row._id);
                  setSelectedApptData(params.row);
                  setOpenPayment(true);
                }}
                color="warning"
                aria-label="payment"
                disabled={params.row.docApproval == 'rejected'}
              >
                <PaymentIcon />
              </IconButton>
            </Tooltip>
          )}

          {params.row.paymentLog.length !== 0 && (
            <Tooltip title="View Transaction History">
              <IconButton
                onClick={() => {
                  setSelectedApptData(params.row);
                  setOpenTransaction(true);
                }}
                color="info"
                aria-label="transaction-history"
                disabled={params.row.docApproval == 'rejected'}
              >
                <HistoryIcon />
              </IconButton>
            </Tooltip>
          )}
          {/* {params.row.docApproval === 'pending' && (
              <>
                <Tooltip title="Approve Appointment">
                  <IconButton
                    onClick={() => {
                      dispatch(updateAppointment({ ...params.row, docApproval: 'approved' })).then(
                        () => {
                          callApi();
                        },
                      );
                    }}
                    color="success"
                    aria-label="approve-appointment"
                  >
                    <CheckCircleOutlineIcon />
                  </IconButton>
                </Tooltip>
                <Tooltip title="Decline Appointment">
                  <IconButton
                    onClick={() => handleDelete(params.row)}
                    color="error"
                    aria-label="decline-appointment"
                  >
                    <CancelIcon />
                  </IconButton>
                </Tooltip>
              </>
            )} */}
        </div>
      ),
    },
    {
      field: 'doctor',
      headerName: <div className="gridHeaderText">Doctor Name</div>,
      renderCell: (params) => (
        <div>{params && params.row && (params.row.doctor?.name || params.row.doctorId?.name)}</div>
      ),
      width: 150,
    },
    {
      field: 'patient',
      headerName: <div className="gridHeaderText">Patient Name</div>,
      renderCell: (params) => (
        <div>
          {params && params.row && (params.row.patient?.name || params.row.patientId?.name)}
        </div>
      ),
      width: 170,
    },
    {
      field: 'patient.phone',
      headerName: <div className="gridHeaderText">Patient Phone</div>,
      renderCell: (params) => (
        <div>
          {params && params.row && (params.row.patient?.phone || params.row.patientId?.phone)}
        </div>
      ),
      width: 180,
    },
    {
      field: 'treatment',
      headerName: <div className="gridHeaderText">Treatment</div>,
      width: 200,
    },
    {
      field: 'description',
      headerName: <div className="gridHeaderText">Description</div>,
      width: 300,
    },
    {
      field: 'payment',
      headerName: <div className="gridHeaderText">Payment</div>,
      width: 120,
    },
    {
      field: 'remainingAmount',
      headerName: <div className="gridHeaderText">Remaining</div>,
      width: 120,
    },
    {
      field: 'paidAmount',
      headerName: <div className="gridHeaderText">Paid Amount</div>,
      width: 120,
    },
    {
      field: 'date',
      headerName: <div className="gridHeaderText">Date</div>,
      renderCell: (params) => (
        <div>
          {params && params.row && params.row.date && moment(params.row.date).format('DD/MM/YYYY')}
        </div>
      ),
      width: 150,
    },
    {
      field: 'appointmentDate',
      headerName: <div className="gridHeaderText">Appt. Date</div>,
      renderCell: (params) => (
        <div>
          {params && params.row && params.row.appointmentDate
            ? moment(params.row.appointmentDate).format('DD/MM/YYYY')
            : 'N/A'}
        </div>
      ),
      width: 150,
    },
    {
      field: 'Time',
      headerName: <div className="gridHeaderText">Time</div>,
      renderCell: (params) => (
        <div>
          {params.row.startTime
            ? `${params && params.row && params.row.startTime} To ${
                params && params.row && params.row.endTime
              }`
            : 'N/A'}
        </div>
      ),
      width: 150,
    },
    {
      field: 'visitStatus',
      headerName: <div className="gridHeaderText">Visit Status</div>,
      renderCell: (params) => (
        <div>
          {(params && params.row && params.row.visitStatus == true && (
            <Chip color="success" label="Visited" />
          )) ||
            'N/A'}
        </div>
      ),
      width: 120,
    },
    {
      field: 'docApproval',
      headerName: <div className="gridHeaderText">Appointment Status</div>,
      renderCell: (params) => (
        <div>
          {params && params.row && params.row.docApproval == 'approved' ? (
            <Chip color="success" label="Approved" />
          ) : params.row.docApproval == 'rejected' ? (
            <Chip color="error" label="Rejected" />
          ) : (
            'N/A'
          )}
        </div>
      ),
      width: 120,
    },
  ];

  return (
    <div className={Style.mainDataTable}>
      <div
        style={{
          display: 'flex',
          justifyContent: 'space-between',
          alignItems: 'center',
          marginBottom: '1rem',
        }}
      >
        <div></div>
        <div style={{ display: 'flex', gap: '1rem' }}>
          <Button
            className={Style.addBtn}
            variant="contained"
            startIcon={<FilterAltIcon />}
            onClick={() => {
              setFilter(!filter);
              setDateRange([
                {
                  startDate: null,
                  endDate: null,
                  key: 'selection',
                  color: '#3d91ff',
                },
              ]);
              setPatientData(null);
              setDoctorData(null);
              setIsDisabled(true);
            }}
          >
            Filter
          </Button>

          <div style={{ display: 'flex', gap: '1rem' }}>
            <div>
              <a
                className={`btn btn-outline-success d-flex align-items-center p-2 ${
                  isDisabled ? 'disabled-link' : ''
                }`}
                href={isDisabled || appointments?.length === 0 ? '#' : reportUrl}
                target="_blank"
                onClick={(e) => {
                  if (appointments && appointments.length === 0) {
                    e.preventDefault();
                    return toast.error('No data found for this filter');
                  }

                  if (isDisabled) {
                    e.preventDefault();
                  }
                }}
              >
                <Button className={Style.addBtn} variant="contained" disabled={isDisabled}>
                  Generate Invoice
                </Button>
              </a>
              <p>{message}</p>
            </div>

            <div>
              <a
                className={`btn btn-outline-success d-flex align-items-center p-2 ${
                  isDisabled ? 'disabled-link' : ''
                }`}
                href={isDisabled || appointments?.length === 0 ? '#' : receiptUrl}
                target="_blank"
                onClick={(e) => {
                  if (appointments && appointments.length === 0) {
                    e.preventDefault();
                    return toast.error('No data found for this filter');
                  }

                  if (isDisabled) {
                    e.preventDefault();
                  }
                }}
              >
                <Button className={Style.addBtn} variant="contained" disabled={isDisabled}>
                  Generate Receipt
                </Button>
              </a>
              <p>{message}</p>
            </div>

            <div>
              <a
                className={`btn btn-outline-success d-flex align-items-center p-2 ${
                  isDisabled ? 'disabled-link' : ''
                }`}
                href={isDisabled || appointments?.length === 0 ? '#' : prescriptionUrl}
                target="_blank"
                onClick={(e) => {
                  if (appointments && appointments.length === 0) {
                    e.preventDefault();
                    return toast.error('No data found for this filter');
                  }

                  if (isDisabled) {
                    e.preventDefault();
                  }
                }}
              >
                <Button className={Style.addBtn} variant="contained" disabled={isDisabled}>
                  Generate Prescription
                </Button>
              </a>
              <p>{message}</p>
            </div>
          </div>
        </div>
      </div>

      {filter && (
        <Card className={Style.tableCard} style={{ marginBottom: '1rem', display: 'flex' }}>
          <div style={{ width: '50%', padding: '1rem' }}>
            <SearchDoctor
              open={filter}
              setData={setDoctorData}
              data={doctorData}
              variant="outlined"
              name="doctor"
            />
          </div>

          <div style={{ width: '50%', padding: '1rem' }}>
            <SearchPatient open={filter} setData={setPatientData} />
          </div>

          <div style={{ width: '50%', padding: '1rem' }}>
            <DateRange
              editableDateInputs={true}
              onChange={(item) => setDateRange([{ ...item.selection, color: '#3d91ff' }])}
              moveRangeOnFirstSelection={false}
              ranges={dateRange}
            />
          </div>
        </Card>
      )}

      <Card className={Style.tableCard}>
        <div className={Style.tableHeader}>
          <h2 className={Style.tableTitle}>Appointment</h2>
          {/* <Button
            className={Style.addBtn}
            variant="contained"
            startIcon={<HealthAndSafetyIcon />}
            onClick={() => navigate('/appointmentform')}
          >
            Add Data
          </Button> */}
        </div>
        <DataGrid
          sx={{
            color: '#000',
            backgroundColor: '#fff',
            fontSize: '1rem',
            height: 'auto',
            fontWeight: '600',
          }}
          rows={appointments || []}
          columns={columns}
          loading={apptLoading}
          pagination
          paginationMode="server"
          rowCount={totalCount}
          initialState={{
            ...appointments?.initialState,
            pagination: {
              ...appointments?.initialState?.pagination,
              paginationModel: {
                pageSize: pageSize,
              },
            },
          }}
          onPageChange={(newPage) => setPage(newPage)}
          onPageSizeChange={(newPageSize) => setPageSize(newPageSize)}
          onPaginationModelChange={handlePaginationModelChange}
          getRowId={(e) => e._id}
        />

        <PatientFormDialog
          open={open}
          editData={editData}
          setOpen={setOpen}
          operationMode={operationMode}
          setOperationMode={setOperationMode}
          callApi={callApi}
        />

        <PaymentDialog
          open={openPayment}
          handleClose={() => setOpenPayment(false)}
          appointmentId={selectedApptId}
          appointmentDetails={selectedApptData?._id}
          callApi={callApi}
        />

        <TransactionHistoryDialog
          open={openTransaction}
          setOpen={setOpenTransaction}
          paymentLog={(selectedApptData && selectedApptData.paymentLog) || []}
        />
      </Card>
    </div>
  );
}
